class Solution {
public:
    int numDecodings(string s) {
        const long long MOD = 1000000007;
        int n = (int)s.size();
        if (n == 0) return 0;
        long long prev2 = 1;
        long long prev1 = (s[0] == '*') ? 9 : (s[0] == '0' ? 0 : 1);
        for (int i = 1; i < n; i++) {
            long long cur = 0;
            char c = s[i];
            char p = s[i - 1];
            // single-character group ending at i
            if (c == '*') {
                cur = (cur + prev1 * 9) % MOD;
            } else if (c != '0') {
                cur = (cur + prev1) % MOD;
            }
            // two-character group ending at i
            long long w2 = 0;
            if (p == '*' && c == '*') {
                w2 = 15; // 11-19 (9) + 21-26 (6)
            } else if (p == '*') {
                if (c >= '0' && c <= '6') w2 = 2; // 1c and 2c
                else w2 = 1; // only 1c
            } else if (c == '*') {
                if (p == '1') w2 = 9; // 11-19
                else if (p == '2') w2 = 6; // 21-26
            } else {
                int v = (p - '0') * 10 + (c - '0');
                if (v >= 10 && v <= 26) w2 = 1;
            }
            cur = (cur + prev2 * w2) % MOD;
            prev2 = prev1;
            prev1 = cur;
        }
        return (int)prev1;
    }
};
